import{z as p,x as A,o,c,q as r,j as n,D as t,d as s,s as i,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"指令调度","description":"","frontmatter":{"title":"指令调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/instruction-sched.md","filePath":"cs/instruction-sched.md","lastUpdated":1791413859000}'),u={name:"cs/instruction-sched.md"};function B(h,a,E,m,f,D){const l=A("Mermaid");return o(),c("div",null,[a[2]||(a[2]=r('<h1 id="指令调度" tabindex="-1">指令调度 <a class="header-anchor" href="#指令调度" aria-label="Permalink to &quot;指令调度&quot;">​</a></h1><div class="epigraph"><p>数据相关与延迟槽决定指令不能任意换序；表调度在基本块内按就绪队列选下一条，缩短占用周期，不改语义。</p><footer>—— 据 Hennessy and Gross, Postpass Code Optimization of Pipeline Constraints, 1983；龙书第 8 章；组成课流水线整理</footer></div><p>上一课<a href="/cs/instruction-select">指令选择</a>交出带虚拟寄存器的机器指令，并声明不排流水线。组成课已有<a href="/cs/data-hazard-forward">数据冒险</a>与<a href="/cs/pipeline-five-stage">五级流水</a>。本课不重选 opcode。缺口是<strong>块内换序</strong>：load 的延迟、乘的延迟、真相关 \\(x\\) 写后读，把指令排成就绪表。寄存器分配尚未发生，调度可与分配交错；主干先调度再着色，或承认二者互相影响。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>选择后的序列合法，但相邻 <code>lw</code> 与用其结果的 <code>add</code> 会停顿。表调度：节点是指令，边是真/反/输出相关，权是延迟。就绪队列里挑使关键路径不拉长的指令发射。缺口是这份 DAG 调度，不是再做转发硬件。</p><p><span class="marginnote">术语翻译：「真相关」就是后一条指令要读前一条刚写的值，数据只能等，换序救不了；「反相关/输出相关」则是两条指令抢同一个寄存器名，换名字就能解开——所以虚拟寄存器无限时，只有真相关才是硬约束。</span></p><p>反相关与输出相关在虚拟寄存器无限时可靠改名削弱；真相关不能消。分配之后物理寄存器会再引入相关，可能要再调度或保守留空。本课以虚拟名上的表调度为对象。</p><h3 id="调度不是超标量发射" tabindex="-1">调度不是超标量发射 <a class="header-anchor" href="#调度不是超标量发射" aria-label="Permalink to &quot;调度不是超标量发射&quot;">​</a></h3><p>超标量硬件同时发多条；本课是编译器静态排单发射或静态 VLIW 槽。组成课的<a href="/cs/superscalar-issue">多发射</a>是硬件；本课不代替 Tomasulo。</p><p><span class="marginnote">Hennessy–Gross 1983 流水约束后处理。龙书 8.10 节指令调度。Appel 有短章。本课块内；跨块（追踪调度）点名不写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建依赖 DAG。拓扑就绪：入度为零。循环：选优先（高度、延迟加权），更新子节点。插 nop 或让硬件停顿——视目标是否暴露延迟槽（经典 MIPS）而定。RISC-V 常靠硬件互锁，调度仍减停顿。</p>',12)),(o(),n(d,null,{default:t(()=>[i(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MI%5B%22%E9%80%89%E5%AE%9A%E7%9A%84%E6%9C%BA%E5%99%A8%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20DEP%5B%22%E7%9B%B8%E5%85%B3%20DAG%22%5D%0A%20%20DEP%20--%3E%20LIST%5B%22%E8%A1%A8%E8%B0%83%E5%BA%A6%22%5D%0A%20%20LIST%20--%3E%20SEQ%5B%22%E6%96%B0%E5%BA%8F%20%2B%20%E5%A1%AB%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/loop-invariant"},"循环不变式"),s(" 外提是另一遍，可在调度前把不变 load 提出块。本课块内不保证最优：表调度是启发式，最优调度难。")],-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},[s("常见误区：初学者容易以为调度器可以随意搬动任何指令；实际上访存要考虑内存别名（保守当成相关边）、"),e("code",null,"volatile"),s(" 与调用是屏障、可能异常的指令不能越过别的指令——合法换序的空间比看上去小得多。")])],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"正确性：尊重真相关与内存别名（保守：可能别名则当相关）。volatile 与调用是屏障。不要调度过可能抛的指令而不顾异常顺序——精确异常要求可见状态；本课整数运算默认可动，访存保守。",-1)),a[7]||(a[7]=e("p",null,"以一个具体块看依赖 DAG 长什么样：三条边全是真相关、真正限制顺序，其余指令是可挪动的填空材料。",-1)),(o(),n(d,null,{default:t(()=>[i(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20I1%5B%221%3A%20lw%20t0%22%5D%20--%3E%20I2%5B%222%3A%20add%20t1%20%E2%86%90%20t0%2Bt3%22%5D%0A%20%20I2%20--%3E%20I5%5B%225%3A%20add%20t7%20%E2%86%90%20t1%2Bt2%22%5D%0A%20%20I3%5B%223%3A%20lw%20t2%20%E7%8B%AC%E7%AB%8B%22%5D%20--%3E%20I5%0A%20%20I4%5B%224%3A%20sub%20t4%20%E7%8B%AC%E7%AB%8B%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">数字实例：经典五级流水里 <code>lw</code> 的结果要到第 4 级才可用，紧跟着用它就得停顿一拍。若块里恰有一条无关指令（上图中的 3 或 4），把它挪进这个空档，就白白省出一个周期的停顿。</span></p><p>与着色：调度拉长同时活区间，冲突图变密，可能多溢出。这是交错的来源，下一课溢出再处理。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不着色、不写窥孔代数。不做软件流水满堂。后课默认：块内指令序已考虑延迟。冲突图着色把虚拟收成物理或 spill。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>表调度按相关 DAG 与延迟排块内序。</li><li>真相关不能改名消掉；别名保守当边。</li><li>可能加长活跃区间，留给分配。</li><li>出处：Hennessy and Gross, 1983；龙书第 8 章。</li></ul>',6))])}const P=p(u,[["render",B]]);export{b as __pageData,P as default};
